	baseTool->RunAndWaitForCompletion();
	baseTool->Close();
	SampleFile = _bstr_t(TheApplication->SamplesDir) + "\\API\\CPP\\e15_Seq_Optimization\\OptimizedFile2.zos";
	TheSystem->SaveAs(SampleFile);
	//! [e15s08_cp]

	//! [e15s09_cp]
	// setup a few variables
