		baseToolHammer->Cancel();
		baseToolHammer->WaitForCompletion();
		baseToolHammer->Close();
	}
	//! [e15s15_cp]

	TheSystem->Save();

#if defined(_DEBUG)
	// keeps console open when in debug mode
	system("pause");
#endif

	// Clean up
	finishStandaloneApplication(TheApplication);


	return 0;
