	RectVolume2_Drawdata->Opacity = ZemaxOpacity_P50;
	//! [e17s05_cp]

	//! [e17s06_cp]
	//Detector Rectangle
	IObjectTypeSettingsPtr oType_3 = Object_3->GetObjectTypeSettings(ObjectType_DetectorRectangle);
	Object_3->RefObject = 2;
	Object_3->ZPosition = 42;
