	//! [e23s04_cp]

	// initialize x / y image plane arrays
	std::vector<vector<vector<double>>> y_ary(max_num_field, vector<vector<double>>(max_wave, std::vector<double>((max_rays + 1) * (max_rays + 1), 0)));

