    sysFiles = TheSystem.SystemData.Files;
    sysFiles.CoatingFile = 'COATING.DAT';
    sysFiles.ScatterProfile = 'SCATTER_PROFILE.DAT';
    sysFiles.ABgDataFile = 'ABG_DATA.DAT';
    TheSystem.SystemData.Files.ReloadFiles();
    %! [e12s07_m]

